export const payers: Payer[] = [
  { id: "bcbsma", name: "Blue Cross Blue Shield of MA" },
  { id: "hpi", name: "Harvard Pilgrim" },
  { id: "tufts", name: "Tufts Health Plan" },
  { id: "aetna", name: "Aetna" },
  { id: "uhc", name: "UnitedHealthcare" },
];

const BASE_CASH: Record<string, number> = {
  "72148": 1150, "70553": 2100, "73721": 1050, "74177": 1400, "45378": 1900, "29881": 5200,
  "27447": 32000, "59400": 11500, "80053": 45, "99213": 160, G0121: 1750,
};

const HOSPITAL_MULT: Record<string, number> = {
  longwood: 1.55, charles: 1.4, harbor: 1.25, backbay: 2.6, mystic: 0.72,
  bluehills: 0.85, neponset: 0.65, newton: 1.05, unionsq: 0.9,
};

/** Hospital/code pairs intentionally absent to demonstrate missing-data states. */
const NOT_PUBLISHED = new Set(["neponset:27447", "neponset:59400", "backbay:59400", "unionsq:27447", "mystic:70553"]);

function mulberry32(seed: number) {
  return () => {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function buildRecords(): PriceRecord[] {
  const rand = mulberry32(72148);
  const out: PriceRecord[] = [];
  const settings: Setting[] = ["outpatient", "inpatient"];
  for (const hosp of hospitals) {
    for (const proc of procedures) {
      if (NOT_PUBLISHED.has(`${hosp.id}:${proc.code}`)) continue;
      for (const setting of settings) {
        if (proc.defaultSetting === "inpatient" && setting === "outpatient") continue;
        if (proc.category === "Lab" && setting === "inpatient") continue;
        const settingMult = setting === "inpatient" && proc.defaultSetting === "outpatient" ? 1.35 : 1;
        const cash = (BASE_CASH[proc.code] ?? 0) * (HOSPITAL_MULT[hosp.id] ?? 1) * settingMult * (0.88 + rand() * 0.24);
        const push = (priceType: PriceType, amount: number, payerId: string | null) => {
          const missing = rand() < 0.07;
          out.push({
            id: `${hosp.id}-${proc.code}-${setting}-${priceType}-${payerId ?? "na"}`,
            hospitalId: hosp.id, code: proc.code, priceType, payerId, setting,
            amount: missing ? null : Math.round(amount),
            retrievedAt: hosp.lastRetrieved, sourceUrl: hosp.sourceUrl,
          });
        };
        push("cash", cash, null);
        push("gross", cash * (2.4 + rand() * 1.4), null);
        for (const p of payers) push("negotiated", cash * (0.75 + rand() * 0.7), p.id);
      }
    }
  }
  return out;
}

export const priceRecords: PriceRecord[] = buildRecords();
